const checked='2026-10-12';
const entries={};
const labels={tuition:'Tuition and compulsory fees',fundingDetail:'Funding',selection:'Examinations / supervisor',cycle:'Application calendar'};
function put(id,facts,extra={}){
 const e={...entries[id],...extra,checked,evidence:[],sources:[],audit:{checked,fields:{}}};
 for(const [field,[value,url,status='Verified',year='Current published rule',note='']] of Object.entries(facts)){
  e[field]=value;e.evidence.push({field,text:value,url,checked});e.sources.push({url,label:labels[field]+' — official evidence'});
  e.audit.fields[field]={status,source:url,year,note,checked};
 }
 e.sources.push(...(extra.sources||[]));
 entries[id]=e;
}
