function amend(id,field,fact,extra={}){const old=entries[id];const [value,url,status='Verified',year='Current published rule',note='']=fact;old[field]=value;old.audit.fields[field]={status,source:url,year,note,checked};old.evidence=old.evidence.filter(e=>e.field!==field).concat({field,text:value,url,checked});old.sources.push({url,label:labels[field]+' — specific official source'});Object.assign(old,extra)}
amend('universite-paris-saclay-mathematics-and-applications-fundamental-mathematics','fundingDetail',['The 2026 international master scheme offers EUR 10,000/year (September–June) plus up to EUR 900/year travel/visa support. Applicants must be under 30 and generally first enrolling in France, admitted to an eligible Saclay master and selected by its coordinator. M1 renewal requires progression to an eligible M2; incompatible funding and reduced payments during some mobility/internships apply. The March 2026 selection/application deadlines are historical, not a verified 2027 call.','https://www.universite-paris-saclay.fr/en/admission/bourses-et-aides-financieres/international-masters-scholarships-program','Historical','2026 award call'],{funding:'Competitive scholarship — next call unverified',statistics:'The linked M1 page lists capacity 60 for its 2026 route. This is a programme capacity, not an acceptance rate or an admitted-student grade distribution.'});
